head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.vScrenID = "ULDSTF70034_p2.xml";
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.gubun = "", scwin.select_gubun = "", scwin.dscYn = "";
scwin.listBzTpCd = "794"; // 디지털증권 상장폐지 
scwin.trsIdx; // insert, update 구분

scwin.isFirstLoad = false;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_search = function() {
    if (scwin.fr_bz_procs_no != "") {
        var url = "/digital/DigitalListinvstg.do?method=selectDigitalDelist&DIV_IDX=" + DIV_IDX_DIGITAL_DELLIST_MST + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Mst.DataID = encodeURI(url);
        dts_Mst.reset();
        url = "/digital/DigitalListinvstg.do?method=selectDigitalDelist&DIV_IDX=" + DIV_IDX_DIGITAL_DELLIST_DTL + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        dts_Isu.DataID = encodeURI(url);
        dts_Isu.reset();
    }
};
scwin.fn_new_onload = function() {
    /* useupdate를 false로 지정함. */
    var url = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DIGITAL_DELLIST_MST_INOUT";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //dts_Mst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELLIST_MST_INOUT";
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();

    /* useupdate를 false로 지정함. */
    dts_Isu.DataID = "/digital/DigitalListinvstg.do?method=selectDigitalDelist&DIV_IDX=" + DIV_IDX_DIGITAL_DELLIST_DTL + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&GUBUN_CD=" + $c.ut.cGetToday("yyyymmdd");
    dts_Isu.reset();
};
scwin.fn_CheckForm = function() {
    if (dts_Isu.getTotalRow() == 0) {
        $c.win.alert("[상장폐지종목]을 선택하세요.");
        return false;
    }
    if (!$c.lcd.checkDdTm("DD", edt_DelistDd, "상장폐지", false)) return false;
    if (!$c.stf.checkEmptyValue(txb_GrndRegulNm, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txb_GrndRegulNm, 200, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txa_Remk, 2000, "기타")) return false;
    return true;
};
scwin.fn_save_trs = function() {
    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_Isu.NameString(i, "BZ_PROCS_NO") = fr_bz_procs_no;*/
        X = scwin.fr_bz_procs_no;
    }


    // ELW는 항상  종목별기준으로 처리함
    // 1 : 종목별 , 2 : 법인별
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MKTACT_APPL_OBJ_TP_CD", "1");
    //dts_Mst.NameString(dts_Mst.RowPosition, "ISUR_CD") =  Isur_cd;
    //dts_Mst.NameString(dts_Mst.RowPosition, "DELIST_RSN_CD") =  dts_Rsn.NameString(dts_Rsn.RowPosition, "CODE")  ;
    //dts_Mst.NameString(dts_Mst.RowPosition, "DELIST_RSN_DSC") =  dts_Rsn.NameString(dts_Rsn.RowPosition, "NAME")  ;
    //dts_Mst.NameString(dts_Mst.RowPosition, "DELIST_RSN_CD") =  dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE")  ;

    //alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;

    var vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx == TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx == TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.Action = $c.lcd.fn_encodeNSession("/digital/DigitalListinvstg.do?method=saveDigitalDelist&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD);
    trs.KeyName = "toinb_dataid4";
    trs.KeyValue = "JSP(I:dtsParm1= dts_Mst , I:dtsParm2= dts_Isu)";
    trs.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.fr_bz_procs_no + ",COUNT=2" + ",LIST_BZ_TP_CD=" + scwin.listBzTpCd + ",DIV_IDX[0]=" + DIV_IDX_DIGITAL_DELLIST_MST + ",DIV_IDX[1]=" + DIV_IDX_DIGITAL_DELLIST_DTL;
    trs.Post();
};
scwin.fn_dupCheck = function(pUpdate) {
    var delistDate = $c.stf.getObjectValue(edt_DelistDd);
    var isuCd = dts_Isu.getCellData(1, "ISU_CD");
    var bzProcsNo = dts_Isu.getCellData(1, "BZ_PROCS_NO");
    var isNotDup = true;
    var url = "/digital/DigitalListinvstg.do?method=searchDigitalDupDelist" + "&ISU_CD=" + isuCd + "&DELIST_DD=" + delistDate;
    if (pUpdate) url += "&BZ_PROCS_NO=" + bzProcsNo;
    dts_DupIsu.DataID = encodeURI(url);
    dts_DupIsu.reset();
    var dupIsuCd = dts_DupIsu.getCellData(1, "ISU_CD");
    if (dts_DupIsu.getTotalRow() > 0) {
        isNotDup = false;
        $c.win.alert("동일한 날짜에 상장폐지 지정된 종목이 존재합니다.");
    }
    return isNotDup;
};
scwin.fn_save = function() {
    if (scwin.fn_CheckForm() && scwin.fn_dupCheck()) {
        if (!$c.lcd.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", "99999");
            scwin.fn_save_trs();
        }
    }
};
scwin.fn_update = function() {
    if (scwin.fn_CheckForm() && scwin.fn_dupCheck(true)) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lcd.fn_isProcess('U')) return;
        scwin.fn_save_trs();
    }
};
scwin.fn_delete = function() {
    // 공시 체크
    if (!$c.lcd.fn_check_delete_discls(dts_BzProcsNo, scwin.fr_bz_procs_no)) return;
    if (!$c.lcd.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_save_trs();
};


/********************************************** 
 * 함수명 : fn_checkModifyDts()
 * 설명    : 안내문작성 시, 수정사항 체크
 ***********************************************/
scwin.fn_checkModifyDts = function() {
    var rtn = false;
    if ($c.cp.isModified(dts_Mst) == false) {
        rtn = true;
    } else {
        $c.win.alert("변경된 내용이 있습니다. [수정] 후 진행하세요.");
        rtn = false;
    }
    return rtn;
};
scwin.fn_dscl = async function() {
    if (scwin.fn_checkModifyDts() == false) {
        return;
    }
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2) {
        //dts_Mst.NameString(dts_Mst.RowPosition, "ISU_NM") = dts_Isu.NameString(dts_Isu.RowPosition, "ISU_NM");

        arr[0] = "69544";
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = '1';
        //arr[4]; //ctnt
        arr[5] = dts_Isu.getCellData(dts_Isu.getRowPosition(), "ISU_NM");
        //arr[5] = fn_GetAddTitle(dts_Mst.NameValue(dts_Mst.RowPosition, "COM_NM")); //add  title

        $c.stf.CopyDataSet(dts_Isu, param_dts_isu);
        $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "DELIST_RSN_NM", dts_Mst.getCellData(dts_Mst.getRowPosition(), "DELIST_RSN_DSC"));
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_NM", dts_Isu.getCellData(dts_Isu.getRowPosition(), "ISU_NM"));
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 15;
    var hgt = 785 + 40;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_drft = function() {

};
scwin.fn_makt = function() {

};

/********************************************** 
 * 함수명 : dateForm()
 * 설명    : 년월일 포맷 맞춤 (안내문 작성에서 사용)
 ***********************************************/
scwin.dateForm = function(pStr) {
    var str = "";
    if (pStr == "") {
        str = "★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(2, 4) + "년 " + pStr.substring(4, 6) + "월 " + pStr.substring(6, 8) + "일";
    }
    return str;
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_DelistDd_onclick = function() {
    edt_DelistDd.focus();
    popUpCalendar2(edt_DelistDd);
};
scwin.trs_OnFail = function() {
    $c.lcd.fn_alertMsg('F');
};
scwin.trs_OnSuccess = async function() {
    $c.lcd.fn_alertMsg('S');
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_search();
    }
};
scwin.edt_DelistDd_OnKillFocus = function() {
    //fn_setRemk();

};
scwin.gform_onload = function() {
    var fnc = $c.frame.path("../").scwin.fn_GetPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
    var arrPar = new Array();
    if (fnc != undefined) {
        fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
        scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
        scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
        scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
        scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
        scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
        scwin.gubun = (arrPar.length >= 6 ? arrPar[5] : ""); // 발행사/기초자산 구분값
        scwin.select_gubun = (arrPar.length >= 7 ? arrPar[6] : ""); //  구분값
        scwin.dscYn = (arrPar.length >= 8 ? arrPar[7] : ""); //  공시여부

    }

    //alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" + 
    //		 "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  ) ;


    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성


    if (scwin.fr_bz_procs_no != "") {
        // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
        scwin.fn_search();
    } else {
        scwin.fn_new_onload(); // 신규작성시 호출

    }
    $c.cm.PanelToGroupBox(panel_3);
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        scwin.Isur_cd = dts_Isu.getCellData(dts_Isu.getRowPosition(), "ISUR_CD");
        if (scwin.fr_bz_procs_no == "") {
            $c.stf.setObjectValue(edt_DelistDd, $c.ut.cGetPlusDate2(dts_Isu.getCellData(dts_Isu.getRowPosition(), "LSTTRD_DD"), 1));
            $c.stf.setObjectValue(txa_Remk, "최종거래일 " + scwin.dateForm(dts_Isu_Temp.getCellData(dts_Isu_Temp.getFocusedRowIndex(), "LSTTRD_DD")));
        }
    }
};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    if (scwin.fr_bz_procs_no == "") {
        dts_Mst.insertRow();
    }

    // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
    if (scwin.fr_bz_procs_no == "") {
        buttonSet.setInsertStatus();
    } else {
        $c.stf.setButtonSetWithDate(edt_DelistDd, false);
        $c.stf.setButtonSetWithDate2(scwin.dscYn); // 공시여부

    }
};
scwin.dts_Mst_OnLoadError = function() {
    $c.stf.alert_error(dts_Mst);
};
